131	void MultiDiskAdaptor::resetDiskWriterEntries()
132	{
133	  assert(openedDiskWriterEntries_.empty());
134	  diskWriterEntries_.clear();
135	  if (getFileEntries().empty()) {
136	    return;
137	  }
138	  for (auto& fileEntry : getFileEntries()) {
139	    diskWriterEntries_.push_back(createDiskWriterEntry(fileEntry));
140	  }
141	  // TODO Currently, pieceLength_ == 0 is used for unit testing only.
142	  if (pieceLength_ > 0) {
143	    // Check shared piece forward
144	    int64_t lastOffset = 0;
145	    for (auto& dwent : diskWriterEntries_) {
146	      auto& fileEntry = dwent->getFileEntry();
147	      if (fileEntry->isRequested()) {
148	        // zero length file does not affect lastOffset.
149	        if (fileEntry->getLength() > 0) {
150	          lastOffset =
151	              (fileEntry->getLastOffset() - 1) / pieceLength_ * pieceLength_ +
152	              pieceLength_;
153	        }
154	      }
155	      else if (fileEntry->getOffset() < lastOffset) {
156	        // The files which shares last piece are not needed to be
157	        // allocated. They just require DiskWriter
158	        A2_LOG_DEBUG(fmt("%s needs DiskWriter", fileEntry->getPath().c_str()));
159	        dwent->needsDiskWriter(true);
160	      }
161	    }
162	    // Check shared piece backward
163	    lastOffset = std::numeric_limits<int64_t>::max();
164	    for (auto i = diskWriterEntries_.rbegin(), eoi = diskWriterEntries_.rend();
165	         i != eoi; ++i) {
166	      auto& fileEntry = (*i)->getFileEntry();
167	      if (fileEntry->isRequested()) {
168	        lastOffset = fileEntry->getOffset() / pieceLength_ * pieceLength_;
169	      }
170	      else if (lastOffset <= fileEntry->getOffset() || // length == 0 case
171	               lastOffset < fileEntry->getLastOffset()) {
172	        // We needs last part of the file, so file allocation is
173	        // required, especially for file system which does not support
174	        // sparse files.
175	        A2_LOG_DEBUG(
176	            fmt("%s needs file allocation", fileEntry->getPath().c_str()));
177	        (*i)->needsFileAllocation(true);
178	      }
179	    }
180	  }
181	  DefaultDiskWriterFactory dwFactory;
182	  for (auto& dwent : diskWriterEntries_) {
183	    if (dwent->needsFileAllocation() || dwent->needsDiskWriter() ||
184	        dwent->fileExists()) {
185	      A2_LOG_DEBUG(fmt("Creating DiskWriter for filename=%s",
186	                       dwent->getFilePath().c_str()));
187	      dwent->setDiskWriter(dwFactory.newDiskWriter(dwent->getFilePath()));
188	      if (readOnly_) {
189	        dwent->getDiskWriter()->enableReadOnly();
190	      }
191	      // TODO mmap is not enabled at this moment. Call enableMmap()
192	      // after this function call.
193	    }
194	  }
195	}
