281	bool isInRange(DiskWriterEntry* entry, int64_t offset)
282	{
283	  return entry->getFileEntry()->getOffset() <= offset &&
284	         offset < entry->getFileEntry()->getLastOffset();
285	}
286	} // namespace
287	
288	namespace {
289	ssize_t calculateLength(DiskWriterEntry* entry, int64_t fileOffset, ssize_t rem)
290	{
291	  if (entry->getFileEntry()->getLength() < fileOffset + rem) {
292	    return entry->getFileEntry()->getLength() - fileOffset;
293	  }
294	  else {
295	    return rem;
296	  }
297	}
298	} // namespace
299	
300	namespace {
301	class OffsetCompare {
302	public:
303	  bool operator()(int64_t offset, const std::unique_ptr<DiskWriterEntry>& dwe)
304	  {
305	    return offset < dwe->getFileEntry()->getOffset();
306	  }
307	};
308	} // namespace
309	
310	namespace {
311	DiskWriterEntries::const_iterator
312	findFirstDiskWriterEntry(const DiskWriterEntries& diskWriterEntries,
313	                         int64_t offset)
314	{
315	  auto first =
316	      std::upper_bound(std::begin(diskWriterEntries),
317	                       std::end(diskWriterEntries), offset, OffsetCompare());
318	  --first;
319	  // In case when offset is out-of-range
320	  if (!isInRange((*first).get(), offset)) {
321	    throw DL_ABORT_EX(
322	        fmt(EX_FILE_OFFSET_OUT_OF_RANGE, static_cast<int64_t>(offset)));
323	  }
324	  return first;
325	}
326	} // namespace
