328	namespace {
329	void throwOnDiskWriterNotOpened(DiskWriterEntry* e, int64_t offset)
330	{
331	  throw DL_ABORT_EX(
332	      fmt("DiskWriter for offset=%" PRId64 ", filename=%s is not opened.",
333	          static_cast<int64_t>(offset), e->getFilePath().c_str()));
334	}
335	} // namespace
336	
337	void MultiDiskAdaptor::writeData(const unsigned char* data, size_t len,
338	                                 int64_t offset)
339	{
340	  auto first = findFirstDiskWriterEntry(diskWriterEntries_, offset);
341	  ssize_t rem = len;
342	  int64_t fileOffset = offset - (*first)->getFileEntry()->getOffset();
343	  for (auto i = first, eoi = diskWriterEntries_.cend(); i != eoi; ++i) {
344	    ssize_t writeLength = calculateLength((*i).get(), fileOffset, rem);
345	    openIfNot((*i).get(), &DiskWriterEntry::openFile);
346	    if (!(*i)->isOpen()) {
347	      throwOnDiskWriterNotOpened((*i).get(), offset + (len - rem));
348	    }
349	
350	    (*i)->getDiskWriter()->writeData(data + (len - rem), writeLength,
351	                                     fileOffset);
352	    rem -= writeLength;
353	    fileOffset = 0;
354	    if (rem == 0) {
355	      break;
356	    }
357	  }
358	}
359	
360	ssize_t MultiDiskAdaptor::readData(unsigned char* data, size_t len,
361	                                   int64_t offset)
362	{
363	  return readData(data, len, offset, false);
364	}
365	
366	ssize_t MultiDiskAdaptor::readDataDropCache(unsigned char* data, size_t len,
367	                                            int64_t offset)
368	{
369	  return readData(data, len, offset, true);
370	}
371	
372	ssize_t MultiDiskAdaptor::readData(unsigned char* data, size_t len,
373	                                   int64_t offset, bool dropCache)
374	{
375	  auto first = findFirstDiskWriterEntry(diskWriterEntries_, offset);
376	  ssize_t rem = len;
377	  ssize_t totalReadLength = 0;
378	  int64_t fileOffset = offset - (*first)->getFileEntry()->getOffset();
379	  for (auto i = first, eoi = diskWriterEntries_.cend(); i != eoi; ++i) {
380	    ssize_t readLength = calculateLength((*i).get(), fileOffset, rem);
381	    openIfNot((*i).get(), &DiskWriterEntry::openFile);
382	    if (!(*i)->isOpen()) {
383	      throwOnDiskWriterNotOpened((*i).get(), offset + (len - rem));
384	    }
385	
386	    while (readLength > 0) {
387	      auto nread = (*i)->getDiskWriter()->readData(data + (len - rem),
388	                                                   readLength, fileOffset);
389	
390	      if (nread == 0) {
391	        return totalReadLength;
392	      }
393	
394	      totalReadLength += nread;
395	
396	      if (dropCache) {
397	        (*i)->getDiskWriter()->dropCache(nread, fileOffset);
398	      }
399	
400	      readLength -= nread;
401	      rem -= nread;
402	      fileOffset += nread;
403	    }
404	
405	    fileOffset = 0;
406	    if (rem == 0) {
407	      break;
408	    }
409	  }
410	  return totalReadLength;
411	}
412	
413	void MultiDiskAdaptor::writeCache(const WrDiskCacheEntry* entry)
414	{
415	  for (auto& d : entry->getDataSet()) {
416	    A2_LOG_DEBUG(fmt("Cache flush goff=%" PRId64 ", len=%lu", d->goff,
417	                     static_cast<unsigned long>(d->len)));
418	    writeData(d->data + d->offset, d->len, d->goff);
419	  }
420	}
421	
422	void MultiDiskAdaptor::flushOSBuffers()
423	{
424	  for (auto& dwent : openedDiskWriterEntries_) {
425	    auto& dw = dwent->getDiskWriter();
426	    if (!dw) {
427	      continue;
428	    }
429	    dw->flushOSBuffers();
430	  }
431	}
432	
433	bool MultiDiskAdaptor::fileExists()
434	{
435	  return std::find_if(std::begin(getFileEntries()), std::end(getFileEntries()),
436	                      std::mem_fn(&FileEntry::exists)) !=
437	         std::end(getFileEntries());
438	}
439	
440	int64_t MultiDiskAdaptor::size()
441	{
442	  int64_t size = 0;
443	  for (auto& fe : getFileEntries()) {
444	    size += File(fe->getPath()).size();
445	  }
446	  return size;
447	}
448	
449	std::unique_ptr<FileAllocationIterator>
450	MultiDiskAdaptor::fileAllocationIterator()
451	{
452	  return make_unique<MultiFileAllocationIterator>(this);
453	}
454	
455	void MultiDiskAdaptor::enableReadOnly() { readOnly_ = true; }
456	
457	void MultiDiskAdaptor::disableReadOnly() { readOnly_ = false; }
458	
459	void MultiDiskAdaptor::enableMmap()
460	{
461	  for (auto& dwent : diskWriterEntries_) {
462	    auto& dw = dwent->getDiskWriter();
463	    if (dw) {
464	      dw->enableMmap();
465	    }
466	  }
467	}
468	
469	void MultiDiskAdaptor::cutTrailingGarbage()
470	{
471	  for (auto& dwent : diskWriterEntries_) {
472	    int64_t length = dwent->getFileEntry()->getLength();
473	    if (File(dwent->getFilePath()).size() > length) {
474	      // We need open file before calling DiskWriter::truncate(int64_t)
475	      openIfNot(dwent.get(), &DiskWriterEntry::openFile);
476	      dwent->getDiskWriter()->truncate(length);
477	    }
478	  }
479	}
480	
481	size_t MultiDiskAdaptor::utime(const Time& actime, const Time& modtime)
482	{
483	  size_t numOK = 0;
484	  for (auto& fe : getFileEntries()) {
485	    if (fe->isRequested()) {
486	      File f{fe->getPath()};
487	      if (f.isFile() && f.utime(actime, modtime)) {
488	        ++numOK;
489	      }
490	    }
491	  }
492	  return numOK;
493	}
494	
495	} // namespace aria2
