218	    //        util::itos(entry->getFileEntry()->getOffset()).c_str()));
219	    auto& openedFileCounter = getOpenedFileCounter();
220	    if (openedFileCounter) {
221	      openedFileCounter->ensureMaxOpenFileLimit(1);
222	    }
223	    (entry->*open)();
224	    openedDiskWriterEntries_.push_back(entry);
225	  }
226	  else {
227	    // A2_LOG_NOTICE(fmt("DiskWriterEntry: Cache HIT. offset=%s",
228	    //        util::itos(entry->getFileEntry()->getOffset()).c_str()));
229	  }
230	}
